fn sort(vec: Vec<Int>) -> Vec<Int> {
    let mut sorted = vec;
    let len = len(&sorted);
    for i in 0..len {
        for j in 0..(len - i - 1) {
            if sorted[j] > sorted[j + 1] {
                let temp = sorted[j];
                sorted[j] = sorted[j + 1];
                sorted[j + 1] = temp;
            }
        }
    }
    sorted
}

